package com.bank.capalloc.service;

import java.util.logging.Logger;

// 0/1 Knapsack tabulation collapsed to a single row (reverse capacity loop).
public class CapitalAllocationService {
    private static final Logger log = Logger.getLogger(CapitalAllocationService.class.getName());

    public long bestProfit(int[] capital, int[] profit, int budget) {
        long[] dp = new long[budget + 1];                  // dp[c] = best profit at budget c
        for (int i = 0; i < capital.length; i++) {
            for (int c = budget; c >= capital[i]; c--) {    // DOWNWARD → each deal used once
                dp[c] = Math.max(dp[c], profit[i] + dp[c - capital[i]]);
            }
        }
        final long result = dp[budget];
        log.info(() -> "Best profit within budget " + budget + " = " + result);
        return dp[budget];
    }
}
