package com.bank.capalloc;

import com.bank.capalloc.service.CapitalAllocationService;
import java.util.logging.Logger;

public class CapitalAllocationApplication {
    private static final Logger log = Logger.getLogger(CapitalAllocationApplication.class.getName());

    public static void main(String[] args) {
        CapitalAllocationService service = new CapitalAllocationService();
        int[] capital = {1, 3, 4, 5};                      // capital each deal needs
        int[] profit = {1, 4, 5, 7};                       // profit each deal returns
        long best = service.bestProfit(capital, profit, 7); // budget = 7
        log.info(() -> "Final allocated profit = " + best);
    }
}
